    interview = [{'topic': 'behavioral', 'difficulty': 'easy', 'prompt': 'Tell me about yourself and walk me through your resume.', 'guidance_notes': 'Clear structure (present -> past -> future), relevance to the role, no rambling, confident delivery without reading verbatim from resume.'}, {'topic': 'behavioral', 'difficulty': 'medium', 'prompt': 'Describe a time you disagreed with a teammate or manager. How did you handle it?', 'guidance_notes': 'Specific example, ownership of their own role in the disagreement, constructive resolution, no blame-shifting.'}, {'topic': 'behavioral', 'difficulty': 'medium', 'prompt': "Tell me about a project that failed or didn't go as planned. What did you learn?", 'guidance_notes': 'Honesty about failure, concrete lesson learned, evidence they applied that lesson afterward.'}, {'topic': 'behavioral', 'difficulty': 'hard', 'prompt': 'Describe a situation where you had to make a decision with incomplete information. What was your process?', 'guidance_notes': 'Structured reasoning under uncertainty, risk assessment, willingness to revisit the decision if new info came in.'}, {'topic': 'behavioral', 'difficulty': 'medium', 'prompt': 'Tell me about a time you had to learn something completely new in a short amount of time.', 'guidance_notes': "Learning strategy described concretely, evidence of applying the new skill, awareness of what they still didn't know."}, {'topic': 'behavioral', 'difficulty': 'easy', 'prompt': 'What motivates you to do your best work?', 'guidance_notes': "Specific and genuine (not generic 'passion' answer), tied to concrete examples of when that motivation showed up."}, {'topic': 'behavioral', 'difficulty': 'hard', 'prompt': 'Describe a time you had to give difficult feedback to someone. How did you approach it?', 'guidance_notes': 'Specificity of feedback given, empathy balanced with directness, follow-through on the outcome.'}, {'topic': 'behavioral', 'difficulty': 'medium', 'prompt': 'Tell me about a time you went above and beyond what was expected of you.', 'guidance_notes': "Concrete example with measurable impact, not just 'worked extra hours' without outcome."}, {'topic': 'situational', 'difficulty': 'medium', 'prompt': 'If you were given a task with an unrealistic deadline by your manager, what would you do?', 'guidance_notes': 'Proactive communication over silent overwork or silent refusal, prioritization/scoping discussion, professionalism.'}, {'topic': 'situational', 'difficulty': 'hard', 'prompt': 'You discover a critical bug in production right before a big client demo. What do you do?', 'guidance_notes': 'Triage instinct (severity first), transparent communication to stakeholders, calm under pressure, not hiding the issue.'}, {'topic': 'situational', 'difficulty': 'medium', 'prompt': "A teammate consistently misses deadlines and it's affecting your work. How would you handle it?", 'guidance_notes': 'Direct but respectful conversation first, focus on impact not accusation, escalation only as a last resort.'}, {'topic': 'situational', 'difficulty': 'hard', 'prompt': "You're leading a project and midway realize the original approach won't scale. What do you do?", 'guidance_notes': 'Willingness to raise the issue early rather than push through, cost/benefit framing of pivoting vs continuing, stakeholder communication.'}, {'topic': 'situational', 'difficulty': 'medium', 'prompt': 'If two senior stakeholders give you conflicting priorities, how do you decide what to work on first?', 'guidance_notes': "Seeks clarification/alignment rather than guessing, considers business impact, doesn't quietly pick one side."}, {'topic': 'situational', 'difficulty': 'easy', 'prompt': 'How would you handle being assigned a task you have no experience with?', 'guidance_notes': 'Willingness to ask for help/resources, realistic self-assessment, a plan to get up to speed rather than blind confidence or panic.'}, {'topic': 'technical_conceptual', 'difficulty': 'easy', 'prompt': 'What is the difference between a process and a thread?', 'guidance_notes': 'Memory isolation vs shared memory, overhead differences, correct mention of context switching cost.'}, {'topic': 'technical_conceptual', 'difficulty': 'medium', 'prompt': "Explain the difference between SQL and NoSQL databases, and when you'd choose one over the other.", 'guidance_notes': 'Schema flexibility, consistency vs scalability tradeoffs (ACID vs eventual consistency), a real example of when they used each.'}, {'topic': 'technical_conceptual', 'difficulty': 'medium', 'prompt': 'What is REST, and what makes an API RESTful?', 'guidance_notes': 'Statelessness, resource-based URLs, correct use of HTTP verbs, idempotency concept if they go deep enough.'}, {'topic': 'technical_conceptual', 'difficulty': 'hard', 'prompt': 'How would you design a URL shortening service like bit.ly? Walk me through your approach.', 'guidance_notes': 'Structured approach (requirements -> estimation -> high-level design -> deep dive), encoding scheme, database choice reasoning, caching/scaling mention.'}, {'topic': 'technical_conceptual', 'difficulty': 'medium', 'prompt': 'What is the difference between authentication and authorization?', 'guidance_notes': 'Clear distinction (who you are vs what you can do), a real example involving both, awareness of common implementation mistakes.'}, {'topic': 'technical_conceptual', 'difficulty': 'easy', 'prompt': 'What is version control and why is it important in a team setting?', 'guidance_notes': "Understands collaboration/history/rollback benefits, not just 'it's for saving code', mentions branching if going deeper."}, {'topic': 'technical_conceptual', 'difficulty': 'hard', 'prompt': "Explain how you would approach debugging a production issue you can't reproduce locally.", 'guidance_notes': 'Systematic approach: logs, monitoring, reproducing conditions, staged rollout of fixes, not just guessing.'}, {'topic': 'technical_conceptual', 'difficulty': 'medium', 'prompt': 'What are the tradeoffs between a monolithic architecture and a microservices architecture?', 'guidance_notes': "Deployment/scaling tradeoffs, operational complexity of microservices, doesn't blindly favor microservices as 'always better'."}, {'topic': 'hr', 'difficulty': 'easy', 'prompt': 'Why do you want to work at this company?', 'guidance_notes': "Specific to the company (not generic), evidence of research, alignment between candidate's goals and company's direction."}, {'topic': 'hr', 'difficulty': 'easy', 'prompt': 'Where do you see yourself in 5 years?', 'guidance_notes': "Realistic, shows ambition without being disconnected from the role applied for, no contradiction with company's growth path."}, {'topic': 'hr', 'difficulty': 'medium', 'prompt': 'What is your biggest weakness, and what are you doing about it?', 'guidance_notes': 'Genuine weakness (not a disguised strength), concrete steps being taken to address it, self-awareness.'}, {'topic': 'hr', 'difficulty': 'medium', 'prompt': 'How do you handle stress and pressure at work?', 'guidance_notes': "Concrete coping strategy, example of a high-pressure situation handled well, not just 'I stay calm'."}, {'topic': 'hr', 'difficulty': 'hard', 'prompt': 'Why should we hire you over other candidates?', 'guidance_notes': "Specific value proposition tied to the role's actual needs, confidence without arrogance, avoids generic claims."}, {'topic': 'hr', 'difficulty': 'medium', 'prompt': 'Describe your ideal work environment.', 'guidance_notes': "Self-aware and specific, doesn't contradict what's known about the company's actual culture, not a list of demands."}]

